const menu=document.querySelector('.menu-toggle');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Menüyü kapat':'Menüyü aç');document.querySelector('header').classList.toggle('menu-open',open);menu.textContent=open?'×':'☰';});
document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('header').classList.remove('menu-open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Menüyü aç');menu.textContent='☰';}));
let listings=[],filter='all',expanded=false;
const grid=document.querySelector('#listings'),more=document.querySelector('#more-listings');
function render(){let data=listings.filter(x=>filter==='all'||(filter==='rent'?x.rent:!x.rent));document.querySelector('#result-count').textContent=data.length+' gayrimenkul';grid.replaceChildren();data.slice(0,expanded?data.length:3).forEach(x=>{const a=document.createElement('article');a.className='listing';a.innerHTML=`<a class="listing-image" href="https://remax.com.tr/tr/portfoy/${x.code}" target="_blank" rel="noopener"><img src="${x.image}" alt="${x.town}, ${x.neighborhood} gayrimenkul fotoğrafı" loading="lazy"><span class="tag">${x.rent?'KİRALIK':'SATILIK'}</span><span class="image-arrow" aria-hidden="true">↗</span></a><div class="listing-body"><p class="listing-location">İZMİR / ${x.town.toLocaleUpperCase('tr-TR')}</p><h3>${x.title.toLocaleLowerCase('tr-TR')}</h3><p class="listing-specs">${x.neighborhood} <span>·</span> ${x.rooms} <span>·</span> ${x.area} m²</p><div class="listing-bottom"><strong>${new Intl.NumberFormat('tr-TR').format(x.price)} ₺${x.rent?'<small> / ay</small>':''}</strong><a href="https://remax.com.tr/tr/portfoy/${x.code}" target="_blank" rel="noopener" aria-label="${x.title} ilanını inceleyin">İnceleyin ↗</a></div></div>`;grid.append(a);});more.hidden=expanded||data.length<=3;}
fetch('listings.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(data=>{listings=data;render();}).catch(()=>{grid.innerHTML='<p>Portföy şu anda yüklenemedi. Güncel ilanlar için <a href="https://remax.com.tr/tr/danisman/43800/burcu-onay-tunali?tab=portfoylerim">RE/MAX profilini ziyaret edebilirsiniz.</a></p>';more.hidden=true;});
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;expanded=false;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});render();}));more.addEventListener('click',()=>{expanded=true;render();});
document.querySelector('#contact-form').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target),message=`Merhaba Burcu Hanım, ben ${d.get('name').trim()}.\n${d.get('interest')}.\n${d.get('message').trim()}`;window.open('https://wa.me/905442355466?text='+encodeURIComponent(message),'_blank','noopener,noreferrer');});
const privacy=document.querySelector('#privacy');document.querySelector('#privacy-open').addEventListener('click',()=>privacy.showModal());privacy.querySelector('.dialog-close').addEventListener('click',()=>privacy.close());privacy.addEventListener('click',e=>{if(e.target===privacy){const r=privacy.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)privacy.close();}});document.querySelector('#year').textContent=new Date().getFullYear();
